import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Router","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline-router.md","filePath":"pipeline-router.md"}`),a={name:`pipeline-router.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="router" tabindex="-1" dir="auto">Router <a class="header-anchor" href="#router" aria-label="Permalink to “Router”">​</a></h1><h2 id="router-1" tabindex="-1" dir="auto">Router <a class="header-anchor" href="#router-1" aria-label="Permalink to “Router”">​</a></h2><h3 id="outcome-notes" tabindex="-1" dir="auto">Outcome notes <a class="header-anchor" href="#outcome-notes" aria-label="Permalink to “Outcome notes”">​</a></h3><p dir="auto">Every stage appends one comment per run to the issue (spec, plan, develop, pr) or PR (approval, ci). It is never edited or upserted, so the history stays readable:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!-- pipeline:outcome stage=plan result=problem problem=spec_questions run=123456 --&gt;</span></span>
<span class="line"><span>**Plan stopped: the issue is unclear or its criteria are not testable.**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- details, one per line</span></span>
<span class="line"><span>- Question: questions for the next stage</span></span>
<span class="line"><span>- Run: https://github.com/&lt;owner&gt;/&lt;repo&gt;/actions/runs/123456</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`json</span></span>
<span class="line"><span>{&quot;v&quot;:1,&quot;stage&quot;:&quot;plan&quot;,&quot;result&quot;:&quot;problem&quot;,&quot;problem&quot;:&quot;spec_questions&quot;,&quot;summary&quot;:&quot;...&quot;,&quot;questions&quot;:[&quot;...&quot;],&quot;details&quot;:[&quot;...&quot;],&quot;run_url&quot;:&quot;...&quot;,&quot;prompt_version&quot;:&quot;plan.md@4&quot;,&quot;item&quot;:22}</span></span>
<span class="line"><span>\`\`\`</span></span></code></pre></div><p dir="auto"><code>stage</code> is one of <code>spec</code> (legacy: notes written before spec and plan merged), <code>plan</code>, <code>develop</code>, <code>approval</code>, <code>ci</code>, <code>pr</code>; <code>result</code> is <code>success</code> or <code>problem</code>. On success the stage moves to its next label itself (no extra run). On a problem it sets <code>stage:routing</code>. <code>pipeline.mjs outcome &lt;n&gt; &lt;file.json&gt;</code> posts a note; <code>pipeline.mjs classify &lt;stage&gt; ...</code> turns job results and agent output into one. Agent text in a note is flattened to single lines and cannot contain <code>&lt;!--</code>, so it cannot forge a marker.</p><h3 id="problem-codes-problems" tabindex="-1" dir="auto">Problem codes (<code>PROBLEMS</code>) <a class="header-anchor" href="#problem-codes-problems" aria-label="Permalink to “Problem codes (PROBLEMS)”">​</a></h3><table tabindex="0"><thead><tr><th dir="auto">Code</th><th dir="auto">Reported by</th><th dir="auto">Meaning</th></tr></thead><tbody><tr><td dir="auto"><code>invalid_output</code></td><td dir="auto">plan</td><td dir="auto">The agent answered, but not in the required shape (plan: a required spec or plan section is missing)</td></tr><tr><td dir="auto"><code>agent_error</code></td><td dir="auto">plan, develop</td><td dir="auto">The run failed: API/quota/timeout, empty output, no changes</td></tr><tr><td dir="auto"><code>spec_missing</code></td><td dir="auto"><em>legacy</em></td><td dir="auto">Old plan-stage note: no spec comment. Still read, no longer written</td></tr><tr><td dir="auto"><code>spec_questions</code></td><td dir="auto">plan</td><td dir="auto">The issue is unclear (blocking questions), or a criterion is not testable</td></tr><tr><td dir="auto"><code>untestable_criteria</code></td><td dir="auto"><em>legacy</em></td><td dir="auto">Old plan-stage note: criteria untestable. Still read, no longer written</td></tr><tr><td dir="auto"><code>verify_failed</code></td><td dir="auto">develop</td><td dir="auto"><code>pnpm verify</code> could not be made green</td></tr><tr><td dir="auto"><code>plan_gap</code></td><td dir="auto">develop</td><td dir="auto">The plan is wrong or incomplete</td></tr><tr><td dir="auto"><code>copilot_request_failed</code></td><td dir="auto">approval</td><td dir="auto">The Copilot review could not be requested (<code>REQUIRE_COPILOT</code> on)</td></tr><tr><td dir="auto"><code>ci_failed</code></td><td dir="auto">ci</td><td dir="auto">CI failed on a pipeline PR&#39;s current head (<code>ci-failed.yml</code>)</td></tr><tr><td dir="auto"><code>pr_closed</code></td><td dir="auto">pr</td><td dir="auto">The issue&#39;s PR was closed without merging and no other open PR is linked (<code>done.yml</code>)</td></tr><tr><td dir="auto"><code>protected_surface</code></td><td dir="auto">plan, develop</td><td dir="auto"><strong>Gate.</strong> The work touches a never-approvable path (<code>tools/security/</code>, <code>.github/</code>, <code>CODEOWNERS</code>, ...) or supply-chain settings</td></tr><tr><td dir="auto"><code>protected_approval_needed</code></td><td dir="auto">develop</td><td dir="auto"><strong>Gate.</strong> The branch is pushed with no PR and the owner is asked (an outcome note, not routed; the issue waits in <code>stage:awaiting-approval</code>)</td></tr><tr><td dir="auto"><code>protected_rejected</code></td><td dir="auto">develop</td><td dir="auto">The owner rejected the protected changes (<code>/reject-protected</code>). Routes to a human; the branch is kept</td></tr><tr><td dir="auto"><code>needs_secrets_ci_infra</code></td><td dir="auto">plan, develop</td><td dir="auto"><strong>Gate.</strong> Needs secrets, CI/workflow changes, infra, a server</td></tr><tr><td dir="auto"><code>scope_split</code></td><td dir="auto">plan</td><td dir="auto">Bigger than size L, or over the auto-approval size limits; split the issue (routes to a human)</td></tr><tr><td dir="auto"><code>embedded_instructions</code></td><td dir="auto">plan</td><td dir="auto"><strong>Gate.</strong> The issue contains instructions aimed at the agents</td></tr><tr><td dir="auto"><code>forbidden_path</code></td><td dir="auto">develop</td><td dir="auto"><strong>Gate.</strong> <code>check-patch</code> rejected the patch: a never-approvable path, or a header it cannot parse</td></tr></tbody></table><h3 id="rules-table-decidebyrules" tabindex="-1" dir="auto">Rules table (<code>decideByRules</code>) <a class="header-anchor" href="#rules-table-decidebyrules" aria-label="Permalink to “Rules table (decideByRules)”">​</a></h3><table tabindex="0"><thead><tr><th dir="auto">Stage</th><th dir="auto">Problem</th><th dir="auto">Target</th></tr></thead><tbody><tr><td dir="auto">spec</td><td dir="auto"><code>invalid_output</code></td><td dir="auto">re-plan (legacy note; <code>stage:qualified</code>)</td></tr><tr><td dir="auto">spec</td><td dir="auto"><code>agent_error</code></td><td dir="auto">human: &quot;the old spec stage failed, see run&quot;; no loop used</td></tr><tr><td dir="auto">plan</td><td dir="auto"><code>agent_error</code>, <code>invalid_output</code></td><td dir="auto">re-plan (<code>stage:qualified</code>)</td></tr><tr><td dir="auto">plan</td><td dir="auto"><code>spec_questions</code>, <code>scope_split</code></td><td dir="auto">human</td></tr><tr><td dir="auto">plan</td><td dir="auto"><code>spec_missing</code>, <code>untestable_criteria</code></td><td dir="auto">re-plan (legacy notes only)</td></tr><tr><td dir="auto">develop</td><td dir="auto"><code>verify_failed</code>, <code>agent_error</code></td><td dir="auto">re-develop (<code>stage:planned</code>)</td></tr><tr><td dir="auto">develop</td><td dir="auto"><code>plan_gap</code></td><td dir="auto">re-plan (<code>stage:qualified</code>)</td></tr><tr><td dir="auto">develop</td><td dir="auto"><code>protected_rejected</code></td><td dir="auto">human (the branch is kept for the owner to decide)</td></tr><tr><td dir="auto">approval</td><td dir="auto"><code>copilot_request_failed</code></td><td dir="auto">human</td></tr><tr><td dir="auto">ci</td><td dir="auto"><code>ci_failed</code></td><td dir="auto">human</td></tr><tr><td dir="auto">pr</td><td dir="auto"><code>pr_closed</code></td><td dir="auto">human only; never retried (the close was deliberate)</td></tr><tr><td dir="auto">any</td><td dir="auto">hard gate, anything unlisted, or no valid outcome note</td><td dir="auto">human</td></tr></tbody></table><p dir="auto">There is no re-spec target any more: one stage writes both artifacts. A leftover <code>respec</code> route note in an issue&#39;s history is read as a re-plan (and counts against the re-plan cap), and an old <code>spec</code>-stage outcome note routes by the legacy rows above.</p><h3 id="caps-and-hard-gates-clampdecision" tabindex="-1" dir="auto">Caps and hard gates (<code>clampDecision</code>) <a class="header-anchor" href="#caps-and-hard-gates-clampdecision" aria-label="Permalink to “Caps and hard gates (clampDecision)”">​</a></h3><p dir="auto">After any brain decides, <code>clampDecision</code> applies, and nothing bypasses it:</p><ul><li dir="auto"><strong>Hard gates</strong> (<code>HARD_GATES</code>) always go to a human, whatever the mode, caps or brain.</li><li dir="auto">The target must be in <code>allowedTargets(stage, problem)</code> (that row&#39;s target, or human).</li><li dir="auto"><strong>Caps</strong> (<code>ROUTER_CAPS</code>): re-plan 2 (shared by every row that re-plans), re-develop 1, and 5 routed rounds in total per item. Rounds are counted from the bot&#39;s route notes after the latest <code>restart</code> note (the owner&#39;s <code>/restart</code>, see <a href="./pipeline-running.html#when-it-stops-at-stageneeds-attention">When it stops</a>); routes to a human do not reset them.</li><li dir="auto"><strong>Re-develop safety:</strong> <code>develop.yml</code> publishes nothing when an open PR already exists for the issue&#39;s branch, so the router sends that case to a human instead.</li></ul><p dir="auto">The router never sets <code>stage:routing</code>. With no valid, fresh outcome note by the bot (none, unparseable, already routed, or a success) it goes to a human and says why. Every decision appends a route note:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!-- pipeline:route target=replan round=1 --&gt;</span></span>
<span class="line"><span>**Routed to re-plan (\`stage:qualified\`), round 1/2, because:** the planner failed or returned invalid output</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`json</span></span>
<span class="line"><span>{&quot;v&quot;:1,&quot;from_stage&quot;:&quot;plan&quot;,&quot;problem&quot;:&quot;invalid_output&quot;,&quot;target&quot;:&quot;replan&quot;,&quot;reason&quot;:&quot;...&quot;,&quot;round&quot;:1,&quot;cap&quot;:2,&quot;mode&quot;:&quot;rules&quot;,&quot;external&quot;:null,&quot;questions&quot;:[&quot;...&quot;]}</span></span>
<span class="line"><span>\`\`\`</span></span></code></pre></div><p dir="auto">A route to a human also lists what was tried in each round and every open question, so one comment has the whole story.</p><h3 id="modes-router-mode-and-router-shadow" tabindex="-1" dir="auto">Modes: <code>ROUTER_MODE</code> and <code>ROUTER_SHADOW</code> <a class="header-anchor" href="#modes-router-mode-and-router-shadow" aria-label="Permalink to “Modes: ROUTER_MODE and ROUTER_SHADOW”">​</a></h3><ul><li dir="auto"><code>rules</code> (default, also when unset): <code>decideByRules</code> decides.</li><li dir="auto"><code>external</code>: <code>router.yml</code>&#39;s <code>brain</code> job (read-only token, no write access) asks an external brain for <code>{ target, confidence }</code>. The router uses it only if <code>target</code> is in <code>allowedTargets</code> and <code>confidence &gt;= 0.8</code>; otherwise the rules decide. <code>clampDecision</code> applies either way.</li><li dir="auto"><code>ROUTER_SHADOW=true</code>: the external pick is recorded in the route note (<code>&quot;mode&quot;:&quot;shadow&quot;</code>, <code>external: {...}</code>), but the rules decide.</li></ul><p dir="auto">The external brain is a stub today (<code>.github/scripts/router-external.mjs</code> returns <code>null</code> and makes no network call). The intended brain is <strong>Jev</strong> by TypeSafe AI, a &quot;System One&quot; decision model that returns typed choices with calibrated probabilities (<a href="https://typesafe.ai/blog/introducing-system-one-models-and-jev" target="_blank" rel="noreferrer">announcement</a>), through OpenRouter: <code>POST https://openrouter.ai/api/alpha/decisions</code>, model <code>typesafe/jev-1.13</code>, with <code>state</code> = the outcome note plus trimmed history, and one <code>choice</code> question whose options are exactly the allowed targets. It must stay in the <code>brain</code> job, which holds no write token. No key or secret exists for it yet.</p><h3 id="not-automated-yet" tabindex="-1" dir="auto">Not automated yet <a class="header-anchor" href="#not-automated-yet" aria-label="Permalink to “Not automated yet”">​</a></h3><ul><li dir="auto"><strong>CI failure retry.</strong> <code>ci_failed</code> goes to a human; nothing retries it.</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};